// EfficientIP DDI -- XDM Data Model Rule (Pattern C exemplar)
// Dataset: efficientip_ddi_raw
//
// SPDX-FileCopyrightText: GoCortexIO
// SPDX-License-Identifier: AGPL-3.0-or-later

[MODEL: dataset = efficientip_ddi_raw]

// -- Stage 1: Identify daemon and operation from named/dhcpd/DNS Guardian --
alter
    _pri = arrayindex(regextract(_raw_log, "^<(\\d+)>"), 0),
    _daemon = arrayindex(regextract(_raw_log, "\\s(named|dhcpd|DNSGuardian|kernel)\\["), 0),
    _pid = arrayindex(regextract(_raw_log, "\\[(\\d+)\\]:"), 0),
    _op = arrayindex(regextract(_raw_log, "\\]:\\s+(\\w+)"), 0)

// -- Stage 2: Named-resolver fields (client + query + verdict) -------------
| alter
    _client_addr = arrayindex(regextract(_raw_log, "client\\s+@0x[0-9a-f]+\\s+(\\d{1,3}(?:\\.\\d{1,3}){3})#\\d+"), 0),
    _client_port = arrayindex(regextract(_raw_log, "client\\s+@0x[0-9a-f]+\\s+\\d{1,3}(?:\\.\\d{1,3}){3}#(\\d+)"), 0),
    _query_name = arrayindex(regextract(_raw_log, "\\((\\S+)\\):\\s+(?:answer|query)"), 0),
    _query_type = arrayindex(regextract(_raw_log, "\\sIN\\s+(\\S+)\\s+"), 0),
    _rcode = arrayindex(regextract(_raw_log, "->\\s+(NOERROR|NXDOMAIN|SERVFAIL|REFUSED|FORMERR)"), 0)

// -- Stage 3: Map to XDM ---------------------------------------------------
| alter
    xdm.observer.vendor = "EfficientIP",
    xdm.observer.product = "DDI",
    xdm.source.ipv4 = _client_addr,
    xdm.source.host.ipv4_addresses = arraycreate(coalesce(_client_addr)),
    xdm.source.port = to_integer(to_number(_client_port)),
    xdm.network.dns.query_name = _query_name,
    xdm.network.dns.response_code = _rcode;

// AWS GuardDuty -- XDM Data Model Rule
// Dataset: aws_guardduty_generic_alert_raw
//
// SPDX-FileCopyrightText: GoCortexIO
// SPDX-License-Identifier: AGPL-3.0-or-later

[MODEL: dataset = aws_guardduty_generic_alert_raw ]

// -- Stage 1: Initialise root-level aliases ---------------------------------
// Normalise the Resource and Service JSON objects to support both PascalCase
// and camelCase field naming conventions from the XSIAM parser.
alter
    finding_resource = coalesce(Resource, resource),
    finding_service = coalesce(Service, service)

// -- Stage 2: Extract action-specific sub-objects ---------------------------
| alter
    finding_network = coalesce(finding_service -> Action.NetworkConnectionAction{}, finding_service -> action.networkConnectionAction{}),
    finding_aws_api = coalesce(finding_service -> Action.AwsApiCallAction{}, finding_service -> action.awsApiCallAction{})

// -- Stage 3: Extract common finding fields --------------------------------
| alter
    finding_account_id = coalesce(AccountId, accountId),
    finding_id = coalesce(Id, id),
    finding_region = coalesce(Region, region),
    finding_severity = to_float(coalesce(Severity, severity)),
    finding_severity_band = coalesce(
        _severity_band,
        if(to_float(coalesce(Severity, severity)) < 4.0, "LOW",
           to_float(coalesce(Severity, severity)) < 7.0, "MEDIUM",
           to_float(coalesce(Severity, severity)) < 9.0, "HIGH")),
    finding_type = coalesce(Type, type)
